const runStartedAt = new Date().toISOString();

return [
  {
    json: {
      run_started_at: runStartedAt,
    },
  },
];

const root = $input.first()?.json ?? {};
const entries = Array.isArray(root.entries) ? root.entries : [];
const statusCode = Number(root.statusCode ?? root.status ?? root.error?.statusCode ?? root.error?.status ?? 0);
const hasHttpError = Boolean(root.error) || (Number.isFinite(statusCode) && statusCode >= 400);
const tier1Succeeded = !hasHttpError && Array.isArray(root.entries);

return [
  {
    json: {
      tier1_succeeded: tier1Succeeded,
      entries: tier1Succeeded ? entries : [],
      sourceTotalCount: Number.isFinite(Number(root.totalCount)) ? Number(root.totalCount) : null,
      tier1_status_code: Number.isFinite(statusCode) && statusCode > 0 ? statusCode : null,
      fallbackSummary: {
        mode: tier1Succeeded ? 'list_full' : 'per_id_only',
        failed_list_pages: [],
        list_discovered_count: tier1Succeeded ? entries.length : 0,
        known_gap_count: 0,
        per_id_fetched_count: 0,
        per_id_failures: [],
      },
      stale_reconciliation_allowed: tier1Succeeded,
    },
  },
];

const tier1 = $('Normalize Tier 1 List Result').first().json;
const seen = new Set();
const rows = [];

for (const agreement of tier1.entries ?? []) {
  const relationshipId = agreement.relationship?.id ?? agreement.relationship_id ?? agreement.id;
  if (!relationshipId || seen.has(relationshipId)) continue;
  seen.add(relationshipId);
  rows.push({
    json: {
      relationshipId,
      listAgreement: agreement,
      sourceTotalCount: tier1.sourceTotalCount,
      run_started_at: $('Start Agreement Sync Run').first().json.run_started_at,
      fallbackSummary: tier1.fallbackSummary,
      stale_reconciliation_allowed: true,
      knownGapIds: [],
    },
  });
}

return rows;

const tier1 = $('Normalize Tier 1 List Result').first().json;
if (tier1.tier1_succeeded) return [];

const safeCeiling = 250;
const knownTotalCount = Number(tier1.sourceTotalCount);
const maxPages = Number.isFinite(knownTotalCount) && knownTotalCount > 0
  ? Math.min(knownTotalCount, safeCeiling)
  : safeCeiling;

return Array.from({ length: maxPages }, (_, index) => ({
  json: {
    page: index + 1,
    limit: 1,
    run_started_at: $('Start Agreement Sync Run').first().json.run_started_at,
  },
}));

const pageItems = $input.all();

return [
  {
    json: {
      paginated_page_count: pageItems.length,
      run_started_at: $('Start Agreement Sync Run').first().json.run_started_at,
    },
  },
];

const tier1 = $('Normalize Tier 1 List Result').first().json;
if (tier1.tier1_succeeded) return [];

function nodeItems(name) {
  try {
    return $(name).all();
  } catch (error) {
    return [];
  }
}

function relationshipIdFromAnchorRecord(record) {
  if (!record || typeof record !== 'object') return null;
  return record.relationship?.id ?? record.relationship_id ?? record.id ?? null;
}

const knownIds = $input.all()
  .map((item) => item.json.anchor_relationship_id)
  .filter(Boolean);
const uniqueKnownIds = [...new Set(knownIds)];

const failedListPages = [];
const discoveredById = new Map();
const paginatedItems = nodeItems('Fetch Paginated Agreement Page');

paginatedItems.forEach((item, index) => {
  const pageNumber = Number(item.json.page ?? index + 1);
  const statusCode = Number(item.json.statusCode ?? item.json.status ?? item.json.error?.statusCode ?? item.json.error?.status ?? 0);
  const entries = Array.isArray(item.json.entries) ? item.json.entries : [];
  const failed = Boolean(item.json.error) || (Number.isFinite(statusCode) && statusCode >= 400) || !Array.isArray(item.json.entries);
  if (failed) {
    failedListPages.push(pageNumber);
    return;
  }

  for (const agreement of entries) {
    const relationshipId = relationshipIdFromAnchorRecord(agreement);
    if (!relationshipId || discoveredById.has(relationshipId)) continue;
    discoveredById.set(relationshipId, agreement);
  }
});

const gapIds = uniqueKnownIds.filter((anchor_relationship_id) => !discoveredById.has(anchor_relationship_id));
const fallbackSummary = {
  mode: discoveredById.size > 0 ? 'paginated_with_gaps' : 'per_id_only',
  failed_list_pages: failedListPages,
  list_discovered_count: discoveredById.size,
  known_gap_count: gapIds.length,
  per_id_fetched_count: 0,
  per_id_failures: [],
};

const requestsById = new Map();
for (const [relationshipId, agreement] of discoveredById.entries()) {
  requestsById.set(relationshipId, {
    relationshipId,
    listAgreement: agreement,
    isKnownGap: false,
  });
}
for (const relationshipId of gapIds) {
  requestsById.set(relationshipId, {
    relationshipId,
    listAgreement: null,
    isKnownGap: true,
  });
}

return [...requestsById.values()].map((request) => ({
  json: {
    ...request,
    sourceTotalCount: tier1.sourceTotalCount,
    run_started_at: $('Start Agreement Sync Run').first().json.run_started_at,
    fallbackSummary,
    knownGapIds: gapIds,
    stale_reconciliation_allowed: gapIds.length === 0,
  },
}));

const runStartedAt = $('Start Agreement Sync Run').first().json.run_started_at;
const lastSeenAt = runStartedAt;

function nodeItems(name) {
  try {
    return $(name).all();
  } catch (error) {
    return [];
  }
}

function firstJson(name) {
  const items = nodeItems(name);
  return items.length > 0 ? items[0].json : null;
}

function cleanNumber(value) {
  if (value === undefined || value === null || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function summarizeServices(services) {
  const summary = [];

  for (const service of services) {
    const children = Array.isArray(service.bundle?.services) ? service.bundle.services : [];
    summary.push({
      service_id: service.id ?? null,
      parent_service_id: null,
      service_template_id: service.serviceTemplateId ?? null,
      name: service.name ?? null,
      occurrence: service.billing?.occurrence ?? null,
      trigger: service.billing?.trigger ?? null,
      is_billed_upfront: service.billing?.isBilledUpfront ?? null,
      pricing_type: service.rate?.pricingType ?? null,
      price: cleanNumber(service.rate?.priceAfterDiscount ?? service.rate?.price),
      status: service.status?.type ?? null,
      is_paused: service.isPaused ?? null,
      is_bundle_parent: children.length > 0,
      is_bundle_child: false,
    });

    for (const child of children) {
      summary.push({
        service_id: child.id ?? null,
        parent_service_id: service.id ?? null,
        service_template_id: child.serviceTemplateId ?? null,
        name: child.name ?? null,
        occurrence: service.billing?.occurrence ?? null,
        trigger: service.billing?.trigger ?? null,
        is_billed_upfront: service.billing?.isBilledUpfront ?? null,
        pricing_type: service.rate?.pricingType ?? null,
        price: cleanNumber(child.rate),
        status: service.status?.type ?? null,
        is_paused: service.isPaused ?? null,
        is_bundle_parent: false,
        is_bundle_child: true,
      });
    }
  }

  return summary;
}

const tier1 = firstJson('Normalize Tier 1 List Result') ?? {};
const fallbackRequest = firstJson('Identify Known Agreement Gaps') ?? firstJson('Prepare Tier 1 Agreement Requests') ?? {};
const knownGapIds = Array.isArray(fallbackRequest.knownGapIds) ? fallbackRequest.knownGapIds : [];
const fetchedAgreements = $input.all()
  .map((item) => item.json)
  .filter((agreement) => agreement && agreement.id && !agreement.error);
const fetchedAgreementIds = new Set(fetchedAgreements.map((agreement) => agreement.id));
const perIdFailures = knownGapIds.filter((relationshipId) => !fetchedAgreementIds.has(relationshipId));
const fallbackSummary = {
  ...(fallbackRequest.fallbackSummary ?? tier1.fallbackSummary ?? {
    mode: 'per_id_only',
    failed_list_pages: [],
    list_discovered_count: 0,
    known_gap_count: 0,
    per_id_fetched_count: 0,
    per_id_failures: [],
  }),
  per_id_fetched_count: Math.max(0, knownGapIds.length - perIdFailures.length),
  per_id_failures: perIdFailures,
};
const staleReconciliationAllowed = fallbackSummary.mode === 'list_full' || perIdFailures.length === 0;

const rows = fetchedAgreements.map((agreement) => {
  const services = Array.isArray(agreement.services) ? agreement.services : [];
  const serviceSummary = summarizeServices(services);
  const displayStatus = agreement.status ?? null;

  return {
    anchor_relationship_id: agreement.id,
    agreement_name: agreement.agreementName ?? agreement.name ?? null,
    status: agreement.status ?? null,
    display_status: displayStatus,
    terminated_at: displayStatus === 'terminated' ? agreement.lastUpdatedAt ?? null : null,
    status_synced_at: runStartedAt,
    client_business_id: agreement.client?.business?.id ?? null,
    client_business_name: agreement.client?.business?.name ?? null,
    client_contact_id: agreement.client?.contactId ?? null,
    effective_date: agreement.effectiveDate ?? null,
    last_updated_at: agreement.lastUpdatedAt ?? null,
    raw: {
      ...agreement,
      profitSyncServiceSummary: serviceSummary,
    },
    last_seen_at: lastSeenAt,
  };
});

return [
  {
    json: {
      run_started_at: runStartedAt,
      rowCount: rows.length,
      rows,
      sample: rows.slice(0, 3).map((row) => ({
        anchor_relationship_id: row.anchor_relationship_id,
        agreement_name: row.agreement_name,
        client_business_name: row.client_business_name,
        display_status: row.display_status,
        terminated_at: row.terminated_at,
        serviceCount: row.raw.profitSyncServiceSummary.length,
        bundleChildCount: row.raw.profitSyncServiceSummary.filter((service) => service.is_bundle_child).length,
      })),
      fallbackSummary,
      stale_reconciliation_allowed: staleReconciliationAllowed,
    },
  },
];

const mapped = $('Map Agreement Rows').first().json;

return [
  {
    json: {
      run_started_at: $('Start Agreement Sync Run').first().json.run_started_at,
      upserted_count: $('Upsert Agreements').all().length,
      fallbackSummary: mapped.fallbackSummary,
      stale_reconciliation_allowed: mapped.stale_reconciliation_allowed === true,
    },
  },
];

const upsertedRows = $('Upsert Agreements').all().map((item) => item.json);
const staleRows = $input.all().map((item) => item.json).filter((row) => row.anchor_relationship_id);
const mapped = $('Map Agreement Rows').first().json;
const fallbackSummary = mapped.fallbackSummary ?? {
  mode: 'per_id_only',
  failed_list_pages: [],
  list_discovered_count: 0,
  known_gap_count: 0,
  per_id_fetched_count: 0,
  per_id_failures: [],
};

return [
  {
    json: {
      status: 'ok',
      run_started_at: $('Start Agreement Sync Run').first().json.run_started_at,
      upsertedCount: upsertedRows.length,
      staleRowCount: staleRows.length,
      staleReconciliationAllowed: mapped.stale_reconciliation_allowed === true,
      fallbackSummary,
      steps: [
        {
          name: 'anchor_agreements_sync',
          details: fallbackSummary,
        },
      ],
      staleSample: staleRows.slice(0, 5).map((row) => ({
        anchor_relationship_id: row.anchor_relationship_id,
        agreement_name: row.agreement_name,
        client_business_name: row.client_business_name,
        display_status: row.display_status,
        status_synced_at: row.status_synced_at ?? null,
      })),
      sample: upsertedRows.slice(0, 5).map((row) => ({
        anchor_relationship_id: row.anchor_relationship_id,
        agreement_name: row.agreement_name,
        client_business_name: row.client_business_name,
        display_status: row.display_status,
        serviceCount: row.raw?.profitSyncServiceSummary?.length ?? 0,
      })),
    },
  },
];
